traps.trap1至别离村.txt:
//翠烟门－别离村

	If ($CuiYanMen2AllFinish==2) @Talk3;
	If ($CuiYanMen2AllFinish==3) @Talk4;

@Talk4:
	FadeOut();
	LoadMap("别离村.map");
	If ($BieLiShengAn==1) @Lable1;
	LoadNpc("bielicun.npc");
	LoadObj("bielicun.obj");
	SetPlayerPos(21,157);
	SetPlayerDir(5);
	If($CuiYanMen2CunLanMusic == 0) @Label5;
	PlayMusic("Ks66.wav");

@Label5:	

	FadeIn();
	ShowMessage("别离村");
	Return;

@Lable1:
	LoadNpc("bielicun1.npc");
	LoadObj("bielicun.obj");
	SetPlayerPos(21,157);
	SetPlayerDir(5);
	If($CuiYanMen2CunLanMusic == 0) @Label3;
	PlayMusic("Ks66.wav");

@Label3:	
	If($CuiYanMen2CunLanMusic == 0) @Label4;
	PlayMusic("Ks66.wav");

@Label4:	

	FadeIn();
	ShowMessage("别离村");
	Return;

@Talk3:
	FadeOut();
	SaveNpc();
	LoadMap("别离村.map");
	LoadNpc("bielicun1.npc");
	LoadObj("bielicun.obj");
	SetPlayerPos(21,157);
	SetPlayerDir(5);
	AddNpc("z08-赵无双.ini",22,133,1);
	Assign($CuiYanMen2AllFinish,3);
	If($CuiYanMen2CunLanMusic == 0) @Label2;
	PlayMusic("Ks66.wav");

@Label2:	
	FadeIn();
	ShowMessage("别离村");
	NpcGoto("赵无双",22,155);
	SetNpcDir("赵无双",1);
	Talk(31000,31140);
	NpcGoto("赵无双",22,133);
	DelNpc("赵无双");
	AddToMemo("乘船取道汉阳到中都去找柴嵩。");
	Return;

traps.trap2至翠烟门.txt:
	If ($CuiYanMen2AllFinish >= 2) @Talk4;
	FadeOut();
	LoadMap("翠烟门.map");
	LoadNpc("CuiYM1.npc");
	LoadObj("CuiYM1.obj");
	SetPlayerPos(137,76);
	SetPlayerDir(1);
	If($CuiYanMen2CunLan == 1) @Label1;
	PlayMusic("ks65.wav");

@Label1:	
	If($NaDaoMiJiMusic == 0) @Label2;
	PlayMusic("ks68.wav");

@Label2:	
	FadeIn();
	ShowMessage("翠烟门");
	If ($CuiYanMen2Finish == 1) @Talk1;
	Return;

@Talk1:
	RunScript("带唐影进翠烟门.txt");
	Return;

@Talk4:
	FadeOut();
	LoadMap("翠烟门.map");
	LoadNpc("CuiYM3.npc");
	LoadObj("CuiYM.obj");
	SetPlayerPos(137,76);
	SetPlayerDir(1);
	FadeIn();
	ShowMessage("翠烟门");
	Return;
